-- Publish only explicitly synthetic package examples on assets already in the curated snapshot.
-- No live queries are exposed to anonymous users. Strip all real author/reviewer identities.
update aurora_private.demo_snapshot d set body=jsonb_set(jsonb_set(d.body,'{data,workItems}',
 coalesce((select jsonb_agg(e.value) from jsonb_array_elements(d.body#>'{data,workItems}') e where e.value->>'wbs_code' is null),'[]')||
 coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'workspace_id',x.workspace_id,'asset_id',x.asset_id,'module',x.module,'kind',x.kind,'title',x.title,'description',x.description,'wbs_code',x.wbs_code,'wbs_group',x.wbs_group,'deliverables',x.deliverables,'predecessor_ids',x.predecessor_ids,'dependency_id',x.dependency_id,'acceptance_criteria',x.acceptance_criteria,'owner_label',x.owner_label,'accountable_label',x.accountable_label,'planned_cost',x.planned_cost,'duration_days',x.duration_days,'weight',x.weight,'scope_status',x.scope_status,'scope_note',x.scope_note,'status',x.status,'priority',x.priority,'progress',x.progress,'details',x.details,'start_on',x.start_on,'due_on',x.due_on,'evidence',x.evidence,'client_visible',x.client_visible,'reviewed_by',case when x.reviewed_by is not null then 'demo' else null end,'reviewed_at',x.reviewed_at,'review_note',x.review_note,'created_by','demo','created_at',x.created_at) order by x.asset_id,x.wbs_code)
 from public.aurora_work_items x join public.aurora_workspaces w on w.id=x.workspace_id and w.is_demo
 where x.wbs_code is not null and x.details->>'Demonstração' like 'Escopo, custos, datas,%' and exists(select 1 from jsonb_array_elements(d.body#>'{data,assets}') a where a->>'id'=x.asset_id::text)),'[]')),
 '{data,wbsBaselines}',coalesce((select jsonb_agg(jsonb_build_object('id',b.id,'asset_id',b.asset_id,'module',b.module,'version',b.version,'title',b.title,'note',b.note,'snapshot',b.snapshot,'created_at',b.created_at) order by b.created_at desc)
 from public.aurora_wbs_baselines b join public.aurora_workspaces w on w.id=b.workspace_id and w.is_demo
 where b.title='EAP demonstrativa · versão inicial' and b.note like 'DEMONSTRAÇÃO%' and exists(select 1 from jsonb_array_elements(d.body#>'{data,assets}') a where a->>'id'=b.asset_id::text)),'[]'));
select jsonb_build_object('work_items',jsonb_array_length(body#>'{data,workItems}'),'wbs_packages',(select count(*) from jsonb_array_elements(body#>'{data,workItems}') x where x->>'wbs_code' is not null),'baselines',jsonb_array_length(body#>'{data,wbsBaselines}'),'identities',(select count(*) from jsonb_array_elements(body#>'{data,workItems}') x where x->>'created_by'<>'demo' or coalesce(x->>'reviewed_by','demo')<>'demo')) from aurora_private.demo_snapshot;
